// Tier of a shiny/mega in the "roleta de shinies" catalog (data/shinyTiers.json,
// generated by scripts/shiny/generate-shiny-tiers.mjs). Lookup is by the
// normalized full name, so "Shiny Scizor" (1C) and "Mega Scizor" (1A) stay
// separate entries.
import { canonicalEnemyName } from './enemyNames';
import { parsePokemonName } from './pokemon';
import catalog from './data/shinyTiers.json';

export type ShinyTier = '1A' | '1B' | '1C' | '1H' | '2' | '3';

export const SHINY_TIERS: ShinyTier[] = ['1A', '1B', '1C', '1H', '2', '3'];

export interface TierInfo {
  /** null when the Pokémon isn't in the roulette ("Fora da roleta"). */
  tier: ShinyTier | null;
  /** In the catalog's removed list: it left the roulette. */
  removed: boolean;
}

/** Is the name anywhere in the roulette catalog (current or removed)? */
export function inCatalog(info: TierInfo): boolean {
  return info.tier !== null || info.removed;
}

interface CatalogEntry {
  name: string;
  dex: number;
}
const data = catalog as { tiers: Record<string, CatalogEntry[]>; removed: CatalogEntry[] };

/** Letters and digits only, so catalog spellings ("Mr.Mime", "Rotom (frost)")
 * match the game's ("Mr. Mime", "Rotom (Frost)"). Golden Sudowoodo/Steelix are
 * folded into their Shiny, like everywhere else. */
export function squashName(name: string): string {
  return canonicalEnemyName(name)
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '');
}

const key = squashName;

const TIER_BY_KEY = new Map<string, ShinyTier>();
for (const tier of SHINY_TIERS) for (const entry of data.tiers[tier] ?? []) TIER_BY_KEY.set(key(entry.name), tier);
const REMOVED_KEYS = new Set(data.removed.map((entry) => key(entry.name)));

/** Catalog keys tried for an exported name: the name itself, then (for
 * "Shiny Mega X", which counts as Shiny) the Shiny-only spelling. */
function lookupKeys(enemy: string): string[] {
  const keys = [key(enemy)];
  const parsed = parsePokemonName(enemy);
  if (parsed.species && parsed.variants.includes('shiny') && parsed.variants.includes('mega')) {
    keys.push(key(`Shiny ${parsed.base}`));
  }
  return keys;
}

export function tierOf(enemy: string): TierInfo {
  const keys = lookupKeys(enemy);
  for (const k of keys) {
    const tier = TIER_BY_KEY.get(k);
    if (tier) return { tier, removed: false };
  }
  return { tier: null, removed: keys.some((k) => REMOVED_KEYS.has(k)) };
}

export function tierLabel(tier: ShinyTier | null): string {
  return tier ? `Tier ${tier}` : 'Fora da roleta';
}
